from typing import List, Optional
from pydantic import BaseModel, Field

class ImageGenerationResult(BaseModel):
    """The structured outputs generated by the Image Generation Agent."""
    packshot: str = Field(description="Consistent product packshot URL.")
    lifestyle_scene: str = Field(description="Lifestyle scene URL.")
    promotional_banner: str = Field(description="Promotional banner URL.")

class ImageGenerationResponse(BaseModel):
    """Structured response wrap returned by the Image Generation Agent."""
    status: str = Field(description="Result of execution: 'success' or 'failed'.")
    errors: List[str] = Field(default_factory=list, description="List of processing error messages.")
    generated_images: Optional[ImageGenerationResult] = Field(default=None, description="The generated images URL links.")
